(()=>{document.querySelectorAll(".code-download").forEach(o=>{const b=o.querySelector("button"),t=o.querySelector("textarea");b&&t&&b.addEventListener("click",()=>{const blob=new Blob([t.value||t.textContent||""],{type:"text/plain"}),u=URL.createObjectURL(blob),a=document.createElement("a");a.href=u,a.download=b.dataset.filename||"code.txt",document.body.appendChild(a),a.click(),a.remove(),setTimeout(()=>URL.revokeObjectURL(u),1e3)})}),document.querySelectorAll(".code-toggle").forEach(b=>{b.addEventListener("click",()=>{const p=b.previousElementSibling;if(!p)return;const c=p.classList.toggle("is-collapsed");b.setAttribute("aria-expanded",c?"false":"true"),b.textContent=c?b.dataset.more:b.dataset.less})})})();
